; Shape-specialized example. Edit scripts/inference_kernels.py and regenerate.
; Run: python3 scripts/run_kernel.py row_max
; x: byte 0, 16 words
; out: byte 64, 4 words

; row_max: reduce 4 columns in each of 4 rows
; Generated by scripts/inference_kernels.py. Launch warp 0, mask 0xf.
; All addresses are bytes; R15 is explicitly initialized to zero.
XOR R15, R15, R15
TID R12
ADD R12, R12, R12
ADD R12, R12, R12
ADD R12, R12, R12
ADD R12, R12, R12
ADDI R12, R12, 0
TID R13
ADD R13, R13, R13
ADD R13, R13, R13
ADDI R13, R13, 64
ADDI R14, R15, 1
row_group:
LD_SHARED R0, [R12]
LD_SHARED R1, [R12 + 4]
FLT R2, R0, R1
SUB R2, R15, R2
XOR R3, R0, R1
AND R3, R3, R2
XOR R0, R0, R3
LD_SHARED R1, [R12 + 8]
FLT R2, R0, R1
SUB R2, R15, R2
XOR R3, R0, R1
AND R3, R3, R2
XOR R0, R0, R3
LD_SHARED R1, [R12 + 12]
FLT R2, R0, R1
SUB R2, R15, R2
XOR R3, R0, R1
AND R3, R3, R2
XOR R0, R0, R3
ST_SHARED [R13], R0
ADDI R12, R12, 64
ADDI R13, R13, 16
ADDI R14, R14, -1
BEQ R14, R15, done
BEQ R15, R15, row_group
done: EXIT
